import sys

MOD = 998244353


def bpow(a, b):
    return pow(a % MOD, b, MOD)


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = int(data[1])
    b = int(data[2])

    pless = (a * bpow(b, MOD - 2)) % MOD
    pgreater = ((b - a) * bpow(b, MOD - 2)) % MOD

    CP = [[0] * (n + 2) for _ in range(n + 2)]
    STRONG = [0] * (n + 2)
    ans = [0] * (n + 2)

    def calcCP(nn, s):
        if s == 0:
            CP[nn][s] = 1
        else:
            CP[nn][s] = ((CP[nn - 1][s - 1] * bpow(pgreater, nn - s)) % MOD +
                         (CP[nn - 1][s] * bpow(pless, s)) % MOD) % MOD

    def calcStrong(nn):
        STRONG[nn] = 1
        if nn > 1:
            for i in range(1, nn):
                STRONG[nn] = (STRONG[nn] - (STRONG[i] * CP[nn][i]) % MOD) % MOD

    def calcAns(nn):
        if nn < 2:
            ans[nn] = 0
        else:
            for i in range(1, nn + 1):
                term = (STRONG[i] * CP[nn][i]) % MOD
                mult = (i * (nn - i) + (i * (i - 1)) // 2 +
                        (ans[i] if i < nn else 0) + ans[nn - i])
                ans[nn] = (ans[nn] + (term * mult) % MOD) % MOD
            coef = (1 - (STRONG[nn] * CP[nn][nn]) % MOD) % MOD
            ans[nn] = (ans[nn] * bpow(coef, MOD - 2)) % MOD

    for i in range(n + 1):
        for j in range(i + 1):
            calcCP(i, j)

    for i in range(n + 1):
        calcStrong(i)

    for i in range(n + 1):
        calcAns(i)

    sys.stdout.write(str(ans[n]) + '\n')


main()
